let language='de';
export function getLanguage(){return language;}
export function menuLabel(open){return language==='de'?(open?'Menü schließen':'Menü öffnen'):(open?'Close menu':'Open menu');}
const nodes=[];
const walker=document.createTreeWalker(document.body,NodeFilter.SHOW_TEXT);
while(walker.nextNode()){
  const node=walker.currentNode,key=node.nodeValue.trim();
  if(copy[key])nodes.push({node,key,prefix:node.nodeValue.match(/^\s*/)[0],suffix:node.nodeValue.match(/\s*$/)[0]});
}
const attributes=[
  ['.skip','aria-label','Zum Inhalt','Skip to content'],
  ['.header .brand','aria-label','LYVRA Startseite','LYVRA home'],
  ['.nav','aria-label','Hauptnavigation','Main navigation'],
  ['.facet-tabs','aria-label','Kreative Facetten','Creative facets']
];
export function setLanguage(next,persist=true){
  language=next==='en'?'en':'de';const index=language==='de'?0:1;
  for(const {node,key,prefix,suffix} of nodes){if(node.isConnected)node.nodeValue=prefix+copy[key][index]+suffix;}
  for(const [selector,attribute,de,en] of attributes)document.querySelector(selector)?.setAttribute(attribute,index?en:de);
  document.documentElement.lang=language;
  document.querySelector('#language').value=language;
  document.querySelector('[for="language"]').textContent=index?'Language':'Sprache';
  document.querySelector('#language').setAttribute('aria-label',index?'Website language':'Sprache der Website');
  document.querySelector('.menu').setAttribute('aria-label',menuLabel(document.querySelector('.menu').getAttribute('aria-expanded')==='true'));
  document.querySelector('meta[name="description"]').content=index?'Discover LYVRA: a creative AI identity within 666SOUNDsDESIGn. A universe of electronic music, digital art, stories and emotion.':'Entdecke LYVRA: eine kreative KI-Identität von 666SOUNDsDESIGn. Ein Universum aus elektronischer Musik, digitaler Kunst, Geschichten und Emotion.';
  if(persist){try{localStorage.setItem('lyvra-language',language);}catch{/* Sprache funktioniert auch ohne Browserspeicher. */}}
  document.dispatchEvent(new CustomEvent('lyvra:languagechange',{detail:{language}}));
}
export function initializeLanguage(){
  let saved='de';try{saved=localStorage.getItem('lyvra-language')||'de';}catch{}
  document.querySelector('#language').addEventListener('change',e=>setLanguage(e.target.value));
  setLanguage(saved,false);
}
